void dei_rs_glowplug( void )
{	
	#define USE_GLOWPLUG		(dei_feature_get( DEI_FEAT_DIESEL_START_DELAY )==0)
	
	if( dei_rs_state && USE_GLOWPLUG )
	{
		dei_rs_evt_signal( DEI_RS_EVT_GLOWPLUG_OFF ) ; 	
	}

	#undef USE_GLOWPLUG
}

